from pathlib import Path

APP=Path('src/AppFinal.tsx')
API=Path('src/index-final.ts')
s=APP.read_text()
b=API.read_text()

# Replace catalog + manual form + bulk modal as one stable block.
start=s.index('function ExamCatalog(')
end=s.index('function MasterCalendar(')
new_ui=r'''function ExamCatalog({boot,canEdit}:{boot:Bootstrap;canEdit:boolean}){const[season,setSeason]=useState(boot.seasons.find(s=>s.is_active)?.id||boot.seasons[0]?.id||''),[grade,setGrade]=useState(''),[active,setActive]=useState('1'),[q,setQ]=useState(''),[edit,setEdit]=useState<any|null>(null),[bulk,setBulk]=useState(false);const list=useAsync(()=>api(`/api/exams?season_id=${season}${grade?`&grade_level_id=${grade}`:''}${active?`&active=${active}`:''}${q?`&q=${encodeURIComponent(q)}`:''}`),[season,grade,active,q]);const items=(list.data as any)?.items||[];const remove=async(x:any)=>{if(!confirm(`${x.name} kaydını silmek/pasife almak istiyor musunuz?`))return;await api(`/api/exams/${x.id}`,{method:'DELETE'});list.reload()};const toggle=async(x:any)=>{await api(`/api/exams/${x.id}`,{method:'PATCH',body:JSON.stringify({is_active:!x.is_active})});list.reload()};const exportXlsx=async()=>{const XLSX=await import('xlsx');const rows=items.map((x:any)=>({publisher:x.publisher_name,grade:x.grade_code,exam_type:x.exam_type||'DENEME',difficulty_level:x.difficulty_level||'',subject:x.subject||'',name:x.name,code:x.code,last_order_date:x.last_order_date||'',estimated_ship_date:x.estimated_ship_date||'',application_start_date:x.application_start_date||'',application_end_date:x.application_end_date||'',list_price:Number(x.list_price||0)/100,purchase_price:Number(x.purchase_price||0)/100,sale_price:Number(x.default_sale_price||0)/100,minimum_order:x.minimum_order,active:x.is_active?'evet':'hayır'}));const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(rows),'Denemeler');XLSX.writeFile(wb,'Yildiz-Deneme-Katalogu.xlsx')};return <><Toolbar><select value={season} onChange={e=>setSeason(e.target.value)}>{boot.seasons.map(s=><option value={s.id} key={s.id}>{s.name}</option>)}</select><select value={grade} onChange={e=>setGrade(e.target.value)}><option value="">Tüm sınıflar</option>{boot.grades.map(g=><option value={g.id} key={g.id}>{g.name}</option>)}</select><select value={active} onChange={e=>setActive(e.target.value)}><option value="1">Aktif</option><option value="0">Pasif</option><option value="">Tümü</option></select><SearchBox value={q} set={setQ}/><div className="spacer"/>{canEdit&&<button className="btn" onClick={()=>setBulk(true)}><Upload size={16}/> İçe Aktar</button>}<button className="btn" onClick={exportXlsx}><Download size={16}/> Dışa Aktar</button>{canEdit&&<button className="btn primary" onClick={()=>setEdit({})}><Plus size={16}/> Deneme Ekle</button>}</Toolbar>{list.loading?<Loading/>:<DataTable cols={['Tarih','Sınıf','Tür','Zorluk','Yayınevi','Deneme','Kod','Son Sipariş','Satış','Durum','İşlem']} rows={items.map((x:any)=>[fmtShort(x.application_start_date),x.grade_name,x.exam_type==='DERS_SINAVI'?`Ders · ${x.subject||'—'}`:(x.exam_type||'Deneme'),x.difficulty_level||'—',x.publisher_short||x.publisher_name,x.name,x.code,fmtDate(x.last_order_date),fmtMoney(x.default_sale_price),<Badge key="b" text={x.is_active?'Aktif':'Pasif'} tone={x.is_active?'good':'muted'}/>,canEdit?<Actions key="a"><button onClick={()=>setEdit(x)} title="Düzenle"><Pencil size={15}/></button><button onClick={()=>toggle(x)} title={x.is_active?'Pasif yap':'Aktif yap'}>{x.is_active?<ToggleRight size={17}/>:<ToggleLeft size={17}/>}</button><button className="danger" onClick={()=>remove(x)} title="Sil/Pasife al"><Trash2 size={15}/></button></Actions>:'—'])}/>} {edit&&<ExamModal boot={boot} season={season} item={edit.id?edit:null} close={()=>setEdit(null)} saved={()=>{setEdit(null);list.reload()}}/>}{bulk&&<ExamBulkModal boot={boot} season={season} close={()=>setBulk(false)} saved={()=>{setBulk(false);list.reload()}}/>}</>}
function ExamModal({boot,season,item,close,saved}:{boot:Bootstrap;season:string;item:any|null;close:()=>void;saved:()=>void}){const[b,setB]=useState<any>(item?{...item,list_price:Number(item.list_price||0)/100,purchase_price:Number(item.purchase_price||0)/100,default_sale_price:Number(item.default_sale_price||0)/100}:{season_id:season,publisher_id:boot.publishers[0]?.id,grade_level_id:boot.grades[0]?.id,minimum_order:1,exam_type:'DENEME',difficulty_level:'',is_active:1});const save=async()=>{const payload={...b,list_price:Math.round(Number(b.list_price||0)*100),purchase_price:Math.round(Number(b.purchase_price||0)*100),default_sale_price:Math.round(Number(b.default_sale_price||0)*100),subject:b.exam_type==='DERS_SINAVI'?b.subject||null:b.subject||null,difficulty_level:String(b.difficulty_level||'').trim()||null};await api(item?`/api/exams/${item.id}`:'/api/exams',{method:item?'PATCH':'POST',body:JSON.stringify(payload)});saved()};return <Modal title={item?'Denemeyi düzenle':'Yeni sınav / deneme'} close={close}><FormGrid><Field label="Yayınevi"><select value={b.publisher_id||''} onChange={e=>setB({...b,publisher_id:e.target.value})}>{boot.publishers.map(p=><option value={p.id} key={p.id}>{p.name}</option>)}</select></Field><Field label="Sınıf düzeyi"><select value={b.grade_level_id||''} onChange={e=>setB({...b,grade_level_id:e.target.value})}>{boot.grades.map(g=><option value={g.id} key={g.id}>{g.name}</option>)}</select></Field><Field label="Sınav türü / seri"><input value={b.exam_type||''} onChange={e=>setB({...b,exam_type:e.target.value})} placeholder="DENEME / TÜRKİYE GENELİ / 1. DENEME"/></Field><Field label="Zorluk seviyesi (isteğe bağlı)"><input list="difficulty-levels" value={b.difficulty_level||''} onChange={e=>setB({...b,difficulty_level:e.target.value})} placeholder="KOLAY / ORTA / ZOR"/><datalist id="difficulty-levels"><option value="KOLAY"/><option value="KOLAY-ORTA"/><option value="ORTA"/><option value="ORTA-ÜST"/><option value="ORTA-ZOR"/><option value="ZOR"/><option value="YKS SINAV DÜZEYİ"/><option value="YKS SINAV AYARI"/><option value="MAARİF"/><option value="TG"/></datalist></Field>{String(b.exam_type||'').toUpperCase()==='DERS_SINAVI'&&<Field label="Ders"><select value={b.subject||''} onChange={e=>setB({...b,subject:e.target.value})}><option value="">Seçiniz</option>{boot.subjects.map(s=><option key={s}>{s}</option>)}</select></Field>}<Field label="Sınav / deneme adı"><input value={b.name||''} onChange={e=>setB({...b,name:e.target.value})}/></Field><Field label="Kod"><input value={b.code||''} onChange={e=>setB({...b,code:e.target.value})}/></Field><Field label="Son sipariş"><input type="date" value={b.last_order_date||''} onChange={e=>setB({...b,last_order_date:e.target.value})}/></Field><Field label="Tahmini sevk"><input type="date" value={b.estimated_ship_date||''} onChange={e=>setB({...b,estimated_ship_date:e.target.value})}/></Field><Field label="Uygulama başlangıcı"><input type="date" value={b.application_start_date||''} onChange={e=>setB({...b,application_start_date:e.target.value})}/></Field><Field label="Uygulama bitişi"><input type="date" value={b.application_end_date||''} onChange={e=>setB({...b,application_end_date:e.target.value})}/></Field><Field label="Liste fiyatı (TL)"><input type="number" value={b.list_price||''} onChange={e=>setB({...b,list_price:e.target.value})}/></Field><Field label="Alış fiyatı (TL)"><input type="number" value={b.purchase_price||''} onChange={e=>setB({...b,purchase_price:e.target.value})}/></Field><Field label="Satış fiyatı (TL)"><input type="number" value={b.default_sale_price||''} onChange={e=>setB({...b,default_sale_price:e.target.value})}/></Field><Field label="Minimum sipariş"><input type="number" value={b.minimum_order||1} onChange={e=>setB({...b,minimum_order:e.target.value})}/></Field></FormGrid><ModalActions close={close} save={save}/></Modal>}
function ExamBulkModal({boot,season,close,saved}:{boot:Bootstrap;season:string;close:()=>void;saved:()=>void}){const[rows,setRows]=useState<any[]>([]),[errors,setErrors]=useState<any[]>([]),[busy,setBusy]=useState(false),[summary,setSummary]=useState('');const template=async()=>{const XLSX=await import('xlsx');const sample=[{publisher:'Demo Yayınları',grade:'TYT',exam_type:'1. DENEME',difficulty_level:'ORTA',subject:'',name:'TYT Kurumsal Deneme',code:'DEMO-TYT-01',last_order_date:'2026-09-01',estimated_ship_date:'2026-09-05',application_start_date:'2026-09-10',application_end_date:'2026-09-12',list_price:150,purchase_price:90,sale_price:120,minimum_order:10,active:'evet'}];const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(sample),'Şablon');const notes=[['Alan','Açıklama'],['Maksimum','Tek dosyada 2.000 satır'],['difficulty_level','İsteğe bağlı: KOLAY, ORTA, ZOR vb. Serbest metin kabul edilir.'],['subject','Ders sınavında ders; genel denemede boş bırakılabilir.'],['active','evet/hayır; boşsa evet'],['Tekrar kayıt','Aynı sezon + aynı code varsa mevcut kayıt güncellenir.'],['Yayınevi','Sistemde yoksa temel yayınevi kaydı otomatik oluşturulur.']];XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(notes),'Açıklama');XLSX.writeFile(wb,'Deneme-Yukleme-Sablonu.xlsx')};const headerKey=(v:any)=>String(v??'').trim().toLocaleLowerCase('tr-TR').replace(/[ıİ]/g,'i').replace(/[şŞ]/g,'s').replace(/[ğĞ]/g,'g').replace(/[üÜ]/g,'u').replace(/[öÖ]/g,'o').replace(/[çÇ]/g,'c').replace(/[^a-z0-9]+/g,'_').replace(/^_+|_+$/g,'');const pick=(o:any,...names:string[])=>{const m:any={};Object.entries(o).forEach(([k,v])=>m[headerKey(k)]=v);for(const n of names){const k=headerKey(n);if(m[k]!==undefined&&m[k]!==null&&m[k]!=='')return m[k]}return ''};const dateValue=(v:any,XLSX:any)=>{if(v===null||v===undefined||v==='')return '';if(v instanceof Date&&!isNaN(v.getTime()))return `${v.getFullYear()}-${String(v.getMonth()+1).padStart(2,'0')}-${String(v.getDate()).padStart(2,'0')}`;if(typeof v==='number'){const d=XLSX.SSF.parse_date_code(v);if(d)return `${String(d.y).padStart(4,'0')}-${String(d.m).padStart(2,'0')}-${String(d.d).padStart(2,'0')}`}const s=String(v).trim();const iso=s.match(/^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})$/);if(iso)return `${iso[1]}-${iso[2].padStart(2,'0')}-${iso[3].padStart(2,'0')}`;const tr=s.match(/^(\d{1,2})[./-](\d{1,2})[./-](\d{2,4})$/);if(tr){let y=tr[3];if(y.length===2)y=`20${y}`;return `${y}-${tr[2].padStart(2,'0')}-${tr[1].padStart(2,'0')}`}return s};const isDifficulty=(v:any)=>/^(KOLAY|KOLAY[- ]?ORTA|ORTA|ORTA[- ]?(ÜST|ZOR)|ZOR|YKS|MAARİF|TG)/i.test(String(v||'').trim());const normalizeRow=(o:any,XLSX:any)=>{const examType=String(pick(o,'exam_type','sınav türü','sinav turu','tür','tur')||'DENEME').trim();let subject=String(pick(o,'subject','ders')||'').trim();let difficulty=String(pick(o,'difficulty_level','difficulty','zorluk','zorluk seviyesi','zorluk_seviyesi')||'').trim();if(!difficulty&&subject&&String(examType).toUpperCase()!=='DERS_SINAVI'&&isDifficulty(subject)){difficulty=subject;subject=''}const emptyKey=Object.keys(o).find(k=>k.startsWith('__EMPTY'));const active=pick(o,'active','aktif')|| (emptyKey?o[emptyKey]:'');return {publisher:String(pick(o,'publisher','yayınevi','yayinevi')||'').trim(),grade:String(pick(o,'grade','sınıf','sinif','sınıf düzeyi','sinif duzeyi')||'').trim(),exam_type:examType,difficulty_level:difficulty,subject,name:String(pick(o,'name','deneme','sınav','sinav','sınav adı','sinav adi')||'').trim(),code:String(pick(o,'code','kod')||'').trim(),last_order_date:dateValue(pick(o,'last_order_date','son sipariş','son siparis'),XLSX),estimated_ship_date:dateValue(pick(o,'estimated_ship_date','sevk','tahmini sevk'),XLSX),application_start_date:dateValue(pick(o,'application_start_date','uygulama başlangıç','uygulama baslangic'),XLSX),application_end_date:dateValue(pick(o,'application_end_date','uygulama bitiş','uygulama bitis'),XLSX),list_price:pick(o,'list_price','liste fiyatı','liste fiyati'),purchase_price:pick(o,'purchase_price','alış fiyatı','alis fiyati'),sale_price:pick(o,'sale_price','satış fiyatı','satis fiyati','default_sale_price'),minimum_order:pick(o,'minimum_order','minimum sipariş','minimum siparis')||1,active:active||'evet'}};const validate=(items:any[])=>{const es:any[]=[];if(items.length>2000)es.push({row:0,error:`Tek dosyada en fazla 2000 satır yüklenebilir. Bu dosyada ${items.length} satır var.`});const seen=new Map<string,number>();items.slice(0,2000).forEach((x:any,i)=>{const row=i+2;if(!x.publisher)es.push({row,error:'Yayınevi boş olamaz.'});if(!x.grade)es.push({row,error:'Sınıf düzeyi boş olamaz.'});if(!x.name)es.push({row,error:'Deneme adı boş olamaz.'});if(!x.code)es.push({row,error:'Kod boş olamaz.'});const key=String(x.code||'').trim().toLocaleUpperCase('tr-TR');if(key){if(seen.has(key))es.push({row,error:`Aynı dosyada tekrar eden kod: ${x.code} (ilk satır ${seen.get(key)})`});else seen.set(key,row)}});return es};const file=async(e:React.ChangeEvent<HTMLInputElement>)=>{const f=e.target.files?.[0];if(!f)return;setSummary('');const XLSX=await import('xlsx');const wb=XLSX.read(await f.arrayBuffer(),{cellDates:true});const raw=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{defval:'',raw:true}) as any[];const normalized=raw.filter((o:any)=>Object.values(o).some(v=>String(v??'').trim()!=='')).map(o=>normalizeRow(o,XLSX));const es=validate(normalized);setRows(normalized.slice(0,2000));setErrors(es)};const upload=async()=>{setBusy(true);setSummary('');try{const d=await api('/api/exams/bulk',{method:'POST',body:JSON.stringify({season_id:season,rows})});setErrors(d.errors||[]);setSummary(`${d.created||0} yeni, ${d.updated||0} güncellendi${d.publishers_created?`, ${d.publishers_created} yeni yayınevi oluşturuldu`:''}.`);if(!(d.errors||[]).length)setTimeout(()=>saved(),450)}finally{setBusy(false)}};return <Modal title="Toplu sınav / deneme yükle · 2.000 satır" close={close}><div className="bulk-head"><button className="btn" onClick={template}><FileSpreadsheet size={16}/> Güncel şablonu indir</button><label className="btn"><Upload size={16}/> Excel seç<input hidden type="file" accept=".xlsx,.xls,.csv" onChange={file}/></label></div><div className="info-box">Tek dosyada en fazla <b>2.000 sınav</b>. Excel tarihleri otomatik çevrilir. Zorluk seviyesi isteğe bağlıdır. Eski şablonda <b>subject</b> sütununa yazılmış KOLAY/ORTA/ZOR benzeri değerler de otomatik olarak zorluk seviyesi kabul edilir.</div><p className="muted">{rows.length} satır okundu. Yayınevi sistemde yoksa otomatik temel kayıt açılır; aynı sezon + aynı kod varsa mevcut deneme güncellenir.</p>{rows.length>0&&<DataTable cols={['#','Yayınevi','Sınıf','Tür','Zorluk','Ad','Kod']} rows={rows.slice(0,10).map((x:any,i)=>[i+2,x.publisher,x.grade,x.exam_type,x.difficulty_level||'—',x.name,x.code])}/>} {errors.length>0&&<div className="error-box">{errors.slice(0,30).map((x:any,i)=><div key={`${x.row}-${i}`}>{x.row?`Satır ${x.row}: `:''}{x.error}</div>)}{errors.length>30&&<div>+ {errors.length-30} hata daha</div>}</div>}{summary&&<div className="success-box"><CheckCircle2 size={18}/>{summary}</div>}<div className="modal-actions"><button className="btn" onClick={close}>Vazgeç</button><button className="btn primary" disabled={!rows.length||busy||errors.length>0} onClick={upload}>{busy?'Yükleniyor…':`${rows.length} satırı yükle`}</button></div></Modal>}
'''
s=s[:start]+new_ui+s[end:]

# Backend replace single-create, bulk-create and patch functions.
post_start=b.index("app.post('/api/exams', requireRoles('SUPER_ADMIN','ADMIN')")
bulk_start=b.index("app.post('/api/exams/bulk', requireRoles('SUPER_ADMIN','ADMIN')", post_start)
patch_start=b.index("app.patch('/api/exams/:id', requireRoles('SUPER_ADMIN','ADMIN')", bulk_start)
delete_start=b.index("app.delete('/api/exams/:id'", patch_start)

new_post=r'''app.post('/api/exams', requireRoles('SUPER_ADMIN','ADMIN'), async c => { const x:any=await c.req.json(); if(!x.publisher_id||!x.season_id||!x.grade_level_id||!x.name||!x.code)return fail(c,'Yayınevi, sezon, sınıf, ad ve kod gerekli.'); const rid=uid('exam'); await c.env.DB.prepare(`INSERT INTO exams(id,publisher_id,season_id,grade_level_id,name,code,list_price,purchase_price,default_sale_price,minimum_order,last_order_date,estimated_ship_date,application_start_date,application_end_date,description,status,is_active,exam_type,subject,difficulty_level,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(rid,x.publisher_id,x.season_id,x.grade_level_id,x.name,x.code,Number(x.list_price||0),Number(x.purchase_price||0),Number(x.default_sale_price||0),Number(x.minimum_order||1),x.last_order_date||null,x.estimated_ship_date||null,x.application_start_date||null,x.application_end_date||null,x.description||null,'ACTIVE',x.is_active===0?0:1,x.exam_type||'DENEME',x.subject||null,String(x.difficulty_level||'').trim()||null,now(),now()).run(); await audit(c.env.DB,c.get('user'),'CREATE','exam',rid,undefined,x);return c.json({ok:true,id:rid},201); });
'''

new_bulk=r'''app.post('/api/exams/bulk', requireRoles('SUPER_ADMIN','ADMIN'), async c => {const body:any=await c.req.json().catch(()=>({}));const rows:Array<any>=Array.isArray(body.rows)?body.rows:[];if(!rows.length)return fail(c,'Yüklenecek satır bulunamadı.');if(rows.length>2000)return fail(c,`Tek seferde en fazla 2000 sınav yüklenebilir. Gönderilen: ${rows.length}`);const season=String(body.season_id||'');if(!season)return fail(c,'Sezon seçimi gerekli.');const seasonExists=await c.env.DB.prepare(`SELECT id FROM seasons WHERE id=?`).bind(season).first();if(!seasonExists)return fail(c,'Sezon bulunamadı.',404);const canon=(v:any)=>String(v??'').trim().toLocaleUpperCase('tr-TR').replace(/\s+/g,' ').replace(/[^0-9A-ZÇĞİÖŞÜ]+/g,'');const dateVal=(v:any)=>{if(v===null||v===undefined||v==='')return null;if(typeof v==='number'&&Number.isFinite(v)){const d=new Date(Date.UTC(1899,11,30)+Math.round(v*86400000));return d.toISOString().slice(0,10)}const s=String(v).trim();let m=s.match(/^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})$/);if(m)return `${m[1]}-${m[2].padStart(2,'0')}-${m[3].padStart(2,'0')}`;m=s.match(/^(\d{1,2})[./-](\d{1,2})[./-](\d{2,4})$/);if(m){let y=m[3];if(y.length===2)y=`20${y}`;return `${y}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`}return s};const num=(v:any,def=0)=>{if(v===null||v===undefined||v==='')return def;const n=Number(String(v).trim().replace(/\s/g,'').replace(',','.').replace(/[^0-9.-]/g,''));return Number.isFinite(n)?n:def};const activeVal=(v:any)=>{const x=String(v??'').trim().toLocaleLowerCase('tr-TR');return ['hayır','hayir','h','no','false','0','pasif'].includes(x)?0:1};const diffish=(v:any)=>/^(KOLAY|KOLAY[- ]?ORTA|ORTA|ORTA[- ]?(ÜST|UST|ZOR)|ZOR|YKS|MAARİF|MAARIF|TG)/i.test(String(v||'').trim());const [pubRes,gradeRes,existingRes]=await Promise.all([c.env.DB.prepare(`SELECT id,name,short_name FROM publishers WHERE deleted_at IS NULL`).all<any>(),c.env.DB.prepare(`SELECT id,name,code FROM grade_levels WHERE is_active=1`).all<any>(),c.env.DB.prepare(`SELECT id,code FROM exams WHERE season_id=? AND deleted_at IS NULL`).bind(season).all<any>()]);const pubMap=new Map<string,any>();for(const p of pubRes.results||[])for(const v of [p.id,p.name,p.short_name])if(v)pubMap.set(canon(v),p);const missing=new Map<string,{id:string,name:string}>();for(const x of rows){const raw=String(x.publisher||x.publisher_id||'').trim();if(!raw)continue;const k=canon(raw);if(!pubMap.has(k)&&!missing.has(k))missing.set(k,{id:uid('pub'),name:raw})}if(missing.size){const st=[...missing.values()].map(p=>c.env.DB.prepare(`INSERT INTO publishers(id,name,short_name,minimum_order,default_discount,delivery_days,is_active,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?)`).bind(p.id,p.name,p.name,1,0,14,1,now(),now()));for(let i=0;i<st.length;i+=50)await c.env.DB.batch(st.slice(i,i+50));for(const [k,p] of missing)pubMap.set(k,{id:p.id,name:p.name,short_name:p.name})}const gradeMap=new Map<string,any>();for(const g of gradeRes.results||[])for(const v of [g.id,g.name,g.code])if(v)gradeMap.set(canon(v),g);const existingMap=new Map<string,any>();for(const e of existingRes.results||[])existingMap.set(canon(e.code),e);const seen=new Map<string,number>(),errors:any[]=[],prepared:{row:number;stmt:any;update:boolean}[]=[];for(let i=0;i<rows.length;i++){const x:any=rows[i]||{},row=i+2;const pubRaw=String(x.publisher||x.publisher_id||'').trim(),gradeRaw=String(x.grade||x.grade_level||x.grade_level_id||'').trim(),name=String(x.name||'').trim(),code=String(x.code||'').trim();if(!pubRaw||!gradeRaw||!name||!code){errors.push({row,error:'Yayınevi, sınıf, deneme adı ve kod zorunludur.'});continue}const codeKey=canon(code);if(seen.has(codeKey)){errors.push({row,error:`Aynı dosyada tekrar eden kod: ${code} (ilk satır ${seen.get(codeKey)})`});continue}seen.set(codeKey,row);const pub=pubMap.get(canon(pubRaw)),grade=gradeMap.get(canon(gradeRaw));if(!pub){errors.push({row,error:`Yayınevi eşleştirilemedi: ${pubRaw}`});continue}if(!grade){errors.push({row,error:`Sınıf düzeyi eşleştirilemedi: ${gradeRaw}`});continue}let subject=String(x.subject||'').trim()||null;let difficulty=String(x.difficulty_level||x.difficulty||x.zorluk||x.zorluk_seviyesi||'').trim()||null;const examType=String(x.exam_type||'DENEME').trim()||'DENEME';if(!difficulty&&subject&&examType.toLocaleUpperCase('tr-TR')!=='DERS_SINAVI'&&diffish(subject)){difficulty=subject;subject=null}const old=existingMap.get(codeKey),rid=old?.id||uid('exam');const stmt=c.env.DB.prepare(`INSERT INTO exams(id,publisher_id,season_id,grade_level_id,name,code,list_price,purchase_price,default_sale_price,minimum_order,last_order_date,estimated_ship_date,application_start_date,application_end_date,status,is_active,exam_type,subject,difficulty_level,created_at,updated_at,deleted_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,'ACTIVE',?,?,?,?,?,?,NULL) ON CONFLICT(code,season_id) DO UPDATE SET publisher_id=excluded.publisher_id,grade_level_id=excluded.grade_level_id,name=excluded.name,list_price=excluded.list_price,purchase_price=excluded.purchase_price,default_sale_price=excluded.default_sale_price,minimum_order=excluded.minimum_order,last_order_date=excluded.last_order_date,estimated_ship_date=excluded.estimated_ship_date,application_start_date=excluded.application_start_date,application_end_date=excluded.application_end_date,status='ACTIVE',is_active=excluded.is_active,exam_type=excluded.exam_type,subject=excluded.subject,difficulty_level=excluded.difficulty_level,updated_at=excluded.updated_at,deleted_at=NULL`).bind(rid,pub.id,season,grade.id,name,code,Math.round(num(x.list_price)*100),Math.round(num(x.purchase_price)*100),Math.round(num(x.sale_price??x.default_sale_price)*100),Math.max(1,Math.round(num(x.minimum_order,1))),dateVal(x.last_order_date),dateVal(x.estimated_ship_date),dateVal(x.application_start_date),dateVal(x.application_end_date),activeVal(x.active),examType,subject,difficulty,old?old.created_at||now():now(),now());prepared.push({row,stmt,update:!!old})}let created=0,updated=0;for(let i=0;i<prepared.length;i+=80){const chunk=prepared.slice(i,i+80);try{const rr=await c.env.DB.batch(chunk.map(x=>x.stmt));rr.forEach((r:any,j:number)=>{if(r?.success===false){errors.push({row:chunk[j].row,error:r.error||'Veritabanı işlemi başarısız.'})}else chunk[j].update?updated++:created++})}catch(e){for(const item of chunk){try{await item.stmt.run();item.update?updated++:created++}catch(err){errors.push({row:item.row,error:String(err)})}}}}await audit(c.env.DB,c.get('user'),'BULK_IMPORT','exam',season,undefined,{rows:rows.length,created,updated,publishers_created:missing.size,errors:errors.length});return c.json({ok:true,created,updated,publishers_created:missing.size,errors});});
'''

new_patch=r'''app.patch('/api/exams/:id', requireRoles('SUPER_ADMIN','ADMIN'), async c=>{const rid=c.req.param('id'),x:any=await c.req.json();const old=await c.env.DB.prepare(`SELECT * FROM exams WHERE id=?`).bind(rid).first<any>();if(!old)return fail(c,'Deneme bulunamadı.',404);const n={...old,...x};await c.env.DB.prepare(`UPDATE exams SET publisher_id=?,season_id=?,grade_level_id=?,name=?,code=?,list_price=?,purchase_price=?,default_sale_price=?,minimum_order=?,last_order_date=?,estimated_ship_date=?,application_start_date=?,application_end_date=?,description=?,is_active=?,exam_type=?,subject=?,difficulty_level=?,updated_at=? WHERE id=?`).bind(n.publisher_id,n.season_id,n.grade_level_id,n.name,n.code,Number(n.list_price||0),Number(n.purchase_price||0),Number(n.default_sale_price||0),Number(n.minimum_order||1),n.last_order_date||null,n.estimated_ship_date||null,n.application_start_date||null,n.application_end_date||null,n.description||null,n.is_active?1:0,n.exam_type||'DENEME',n.subject||null,String(n.difficulty_level||'').trim()||null,now(),rid).run();await audit(c.env.DB,c.get('user'),'UPDATE','exam',rid,old,x);return c.json({ok:true})});
'''

b=b[:post_start]+new_post+new_bulk+new_patch+b[delete_start:]

for token in ['difficulty_level','Tek dosyada en fazla <b>2.000 sınav</b>','publishers_created','ON CONFLICT(code,season_id) DO UPDATE']:
    if token not in s+b: raise SystemExit(f'missing expected token {token}')
APP.write_text(s)
API.write_text(b)
